<body>
<div class="game">
  <header>
    <h1>🏴‍☠️ Pocket Pirate Map</h1>
    <div class="sub">Rotate the pirate glyphs, decode the route, then trace it.</div>
  </header>

  <main class="panel">
    <div class="status" id="status">
      Start at the green compass. The glyphs are scrambled. Rotate each glyph until the route reaches the treasure.
    </div>

    <div class="map" id="map"></div>

    <div class="cluebox">
      <div class="label">Captain’s scrambled route:</div>
      <div class="symbols" id="routeSymbols"></div>
    </div>

    <div class="decoder">
      <div class="label">Decoder dials:</div>
      <div class="decoderGrid" id="decoderGrid"></div>
      <div class="hint">
        Tap a dial to rotate its meaning. When your decoded route is valid, the trail will preview on the map.
      </div>
    </div>

    <div class="buttons">
      <button class="action" onclick="resetPath()">Reset Route</button>
      <button class="action" onclick="newMap()">New Map</button>
    </div>

    <div class="win" id="win">Treasure found! The chest is yours. 💰</div>
  </main>
</div>

<script>
const mapEl = document.getElementById("map");
const statusEl = document.getElementById("status");
const routeSymbolsEl = document.getElementById("routeSymbols");
const decoderGridEl = document.getElementById("decoderGrid");
const winEl = document.getElementById("win");

const terrain = ["🌴","🪨","🐚","⚓","🦀","💀","🌊","🗿","☠️"];
const glyphs = ["☀","🌙","🦜","⭐"];
const dirNames = ["Up", "Right", "Down", "Left"];
const dirs = ["U", "R", "D", "L"];
const arrows = { U:"↑", R:"→", D:"↓", L:"←" };
const moves = { U:[-1,0], R:[0,1], D:[1,0], L:[0,-1] };

let trueRoute = [];
let encodedRoute = [];
let decoder = {};
let cells = [];
let currentStep = 0;
let solvedPreview = [];

function posToIndex(r, c) { return r * 5 + c; }

function makeRoute() {
  const routeChoices = [
    ["R","R","D","D","L","D","R","R"],
    ["D","R","R","U","R","D","D","L"],
    ["R","D","D","R","U","R","D","D"],
    ["D","D","R","R","U","R","D","L"]
  ];
  return routeChoices[Math.floor(Math.random() * routeChoices.length)];
}

function buildCells() {
  cells = Array.from({ length: 25 }, () => ({
    icon: terrain[Math.floor(Math.random() * terrain.length)],
    state: "",
    step: ""
  }));
}

function shuffle(arr) {
  return [...arr].sort(() => Math.random() - 0.5);
}

function setupCipher() {
  const shuffledGlyphs = shuffle(glyphs);
  const trueMap = {};
  dirs.forEach((d, i) => trueMap[d] = shuffledGlyphs[i]);
  encodedRoute = trueRoute.map(d => trueMap[d]);

  decoder = {};
  glyphs.forEach((g, i) => {
    decoder[g] = dirs[(i + 1 + Math.floor(Math.random() * 3)) % 4];
  });
}

function decodedDirections() {
  return encodedRoute.map(g => decoder[g]);
}

function positionsFromRoute(route) {
  let r = 0, c = 0;
  const positions = [[r, c]];
  for (const d of route) {
    r += moves[d][0];
    c += moves[d][1];
    if (r < 0 || r > 4 || c < 0 || c > 4) return null;
    positions.push([r, c]);
  }
  return positions;
}

function truePositions() {
  return positionsFromRoute(trueRoute);
}

function checkPreview() {
  const decoded = decodedDirections();
  const positions = positionsFromRoute(decoded);
  if (!positions) {
    solvedPreview = [];
    return false;
  }
  const final = positions[positions.length - 1];
  const treasure = truePositions().at(-1);
  const valid = final[0] === treasure[0] && final[1] === treasure[1];
  solvedPreview = valid ? positions : [];
  return valid;
}

function renderDecoder() {
  decoderGridEl.innerHTML = "";
  glyphs.forEach(g => {
    const card = document.createElement("div");
    card.className = "dial";
    card.innerHTML = `
      <span class="glyph">${g}</span>
      <button type="button">${arrows[decoder[g]]} ${dirNames[dirs.indexOf(decoder[g])]}</button>
    `;
    card.querySelector("button").addEventListener("click", () => rotateGlyph(g));
    decoderGridEl.appendChild(card);
  });
}

function render() {
  mapEl.innerHTML = "";
  const truePos = truePositions();
  const startIndex = posToIndex(0, 0);
  const treasure = truePos[truePos.length - 1];
  const treasureIndex = posToIndex(treasure[0], treasure[1]);
  const previewIndexes = new Set(solvedPreview.map(p => posToIndex(p[0], p[1])));

  cells.forEach((cell, i) => {
    const btn = document.createElement("button");
    btn.className = "cell";
    btn.textContent = cell.icon;
    btn.dataset.step = cell.step || "";

    if (previewIndexes.has(i) && i !== startIndex && !cell.state) btn.classList.add("preview");
    if (i === startIndex) {
      btn.classList.add("start");
      btn.textContent = "🧭";
    }
    if (i === treasureIndex) {
      btn.classList.add("treasure");
      btn.textContent = "💰";
    }
    if (cell.state) btn.classList.add(cell.state);

    btn.addEventListener("click", () => tapCell(i));
    mapEl.appendChild(btn);
  });

  routeSymbolsEl.textContent = encodedRoute.join(" ");
  renderDecoder();
}

function rotateGlyph(glyph) {
  const current = dirs.indexOf(decoder[glyph]);
  decoder[glyph] = dirs[(current + 1) % 4];

  resetPath(false);
  const valid = checkPreview();
  statusEl.textContent = valid
    ? "The decoded trail now reaches the chest. Trace the highlighted route."
    : "That route does not reach the treasure yet. Keep rotating the glyph meanings.";

  render();
}

function tapCell(index) {
  if (!checkPreview()) {
    statusEl.textContent = "Decode the glyphs first. The route must preview before tracing.";
    render();
    return;
  }

  if (currentStep >= trueRoute.length) return;

  const needed = solvedPreview[currentStep + 1];
  const neededIndex = posToIndex(needed[0], needed[1]);

  if (index === neededIndex) {
    currentStep++;
    cells[index].state = "path";
    cells[index].step = currentStep;
    statusEl.textContent = currentStep === trueRoute.length
      ? "X marks the spot. You solved the pirate route."
      : `Correct. Step ${currentStep} of ${trueRoute.length} traced.`;
    if (currentStep === trueRoute.length) winEl.style.display = "block";
  } else {
    cells[index].state = "wrong";
    statusEl.textContent = "Wrong turn. Reset the route and follow the decoded trail.";
  }
  render();
}

function resetPath(showMessage = true) {
  currentStep = 0;
  winEl.style.display = "none";
  cells.forEach(c => {
    c.state = "";
    c.step = "";
  });
  if (showMessage) {
    statusEl.textContent = "Route cleared. Decode and trace again from the compass.";
  }
  render();
}

function newMap() {
  trueRoute = makeRoute();
  buildCells();
  setupCipher();
  currentStep = 0;
  solvedPreview = [];
  winEl.style.display = "none";
  statusEl.textContent = "New pirate map drawn. Rotate the glyphs until the route reaches the treasure.";
  checkPreview();
  render();
}

newMap();
</script>
</body>
</html>

I’ll keep the pocket feel and add replay through three internally defined maps: each has its own route, clue flavor, treasure position, and glyph set, while the existing New Map button simply cycles/randomizes maps instead of opening a menu.

