  decoder[g]=dirs[(dirs.indexOf(decoder[g])+1)%4];
  rotations++;
  resetPath(false);
  statusEl.textContent=checkPreview()
    ?"The decoded trail reaches the chest. Trace the highlighted route."
    :"That route misses the treasure. Keep rotating the glyph meanings.";
  render();
}

function useHint(){
  hints++;
  score=Math.max(0,score-15);
  const wrong=currentMap.glyphs.find(g=>decoder[g]!==solutionDecoder[g]);
  if(wrong){
    decoder[wrong]=solutionDecoder[wrong];
    statusEl.textContent=`Hint used: ${wrong} now points ${arrows[decoder[wrong]]} ${dirNames[dirs.indexOf(decoder[wrong])]}.`;
  }else{
    statusEl.textContent="No hint needed. The decoder is already solved.";
  }
  resetPath(false);
  checkPreview();
  render();
}

function tapCell(index){
  if(!checkPreview()){
    statusEl.textContent="Decode the glyphs first. The route must preview before tracing.";
    render();
    return;
  }
  if(currentStep>=trueRoute.length)return;

  const needed=solvedPreview[currentStep+1],neededIndex=posToIndex(needed[0],needed[1]);

  if(index===neededIndex){
    currentStep++;
    cells[index].state="path";
    cells[index].step=currentStep;
    cursorIndex=index;
    statusEl.textContent=currentStep===trueRoute.length
      ?"X marks the spot. You solved this treasure map."
      :`Correct. Step ${currentStep} of ${trueRoute.length} traced.`;
    if(currentStep===trueRoute.length)winGame();
  }else{
    mistakes++;
    score=Math.max(0,score-10);
    cells[index].state="wrong";
    cursorIndex=index;
    statusEl.textContent="Wrong turn. Reset and follow the decoded trail.";
  }
  render();
}

function winGame(){
  if(score>best){
    best=score;
    localStorage.setItem("pirateMapBestScore",best);
  }
  winEl.style.display="block";
  winEl.innerHTML=`Treasure Log 💰<br>${currentMap.name} solved.<br>Final score: ${score}<br>Hints used: ${hints}<br>Wrong taps: ${mistakes}<br>Decoder turns: ${rotations}<br>Best score: ${best}`;
  updateScore();
}

function resetPath(showMessage=true){
  currentStep=0;
  winEl.style.display="none";
  cursorIndex=0;
  cells.forEach(c=>{c.state="";c.step=""});
  if(showMessage)statusEl.textContent="Route cleared. Decode and trace again from the compass.";
  render();
}

function newMap(){
  mapIndex=(mapIndex+1)%maps.length;
  currentMap=maps[mapIndex];
  trueRoute=currentMap.route;
  buildCells();
  setupCipher();
  currentStep=0;
  solvedPreview=[];
  score=100;
  hints=0;
  mistakes=0;
  rotations=0;
  cursorIndex=0;
  winEl.style.display="none";
  statusEl.textContent=`${currentMap.name} drawn. Rotate the glyphs until the route reaches the treasure.`;
  checkPreview();
  render();
}

function moveCursor(key){
  const [r,c]=indexToPos(cursorIndex);
  let nr=r,nc=c;
  if(key==="ArrowUp")nr--;
  if(key==="ArrowDown")nr++;
  if(key==="ArrowLeft")nc--;
  if(key==="ArrowRight")nc++;
  if(nr<0||nr>4||nc<0||nc>4)return;
  cursorIndex=posToIndex(nr,nc);
  render();
}

document.addEventListener("keydown",e=>{
  const key=e.key.toLowerCase();

  if(["arrowup","arrowdown","arrowleft","arrowright"].includes(key)){
    e.preventDefault();
    moveCursor(e.key);
    return;
  }
  if(key==="enter" || key===" "){
    e.preventDefault();
    tapCell(cursorIndex);
    return;
  }
  if(key==="h"){
    e.preventDefault();
    useHint();
    return;
  }
  if(key==="r"){
    e.preventDefault();
    resetPath();
    return;
  }
  if(key==="n"){
    e.preventDefault();
    newMap();
    return;
  }
  if(["1","2","3","4"].includes(key)){
    const idx=Number(key)-1;
    if(currentMap && currentMap.glyphs[idx]){
      e.preventDefault();
      rotateGlyph(currentMap.glyphs[idx]);
    }
  }
});

newMap();
</script>
</body>
</html>
